import { test, expect } from '@playwright/test';

test.describe('Username Pre-fill on Login', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should pre-fill username if user has logged in before', async ({ page }) => {
    // Mock successful login response
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Intercept and mock user data response
    await page.route('**/api/user/profile', (route) => {
      route.abort('blockedbyclient');
    });

    // Mock user profile API call
    await page.route('**/api/user/profile', (route) => {
      route.continue();
    });

    // Set up localStorage with previous username
    localStorage.setItem('user_profile', JSON.stringify({ username: 'johndoe123' }));

    // Get username input field by role
    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toBeVisible();

    // Verify username is pre-filled
    await expect(usernameInput).toHaveValue('johndoe123');

    // Fill password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('SecurePassword123');

    // Get login button by role
    const loginButton = page.getByRole('button', { name: 'Log In' });
    await loginButton.click();

    // Wait for navigation to dashboard
    await page.waitForURL('**/dashboard');

    // Verify user is logged in
    const welcomeMessage = page.getByText('Welcome, johndoe123');
    await expect(welcomeMessage).toBeVisible();
  });

  test('should not pre-fill username if no previous login exists', async ({ page }) => {
    // Clear localStorage to ensure no previous login data exists
    localStorage.clear();

    // Mock successful login response
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Mock user profile API call
    await page.route('**/api/user/profile', (route) => {
      route.continue();
    });

    // Get username input field by role
    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toBeVisible();

    // Verify username input is empty
    await expect(usernameInput).toHaveValue('');

    // Fill username and password
    await usernameInput.fill('newuser');
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('SecurePassword123');

    // Get login button by role
    const loginButton = page.getByRole('button', { name: 'Log In' });
    await loginButton.click();

    // Wait for navigation to dashboard
    await page.waitForURL('**/dashboard');

    // Verify user is logged in
    const welcomeMessage = page.getByText('Welcome, newuser');
    await expect(welcomeMessage).toBeVisible();
  });
});
